import {chromium} from '@playwright/test';import fs from 'node:fs/promises';import assert from 'node:assert/strict';import {KEY,scenarioState,makeAnalysis} from '../src/model.js';
const dir='检查记录/评估主页面整合_20261022';await fs.mkdir(dir+'/实际截图',{recursive:true});const b=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']});const p=await b.newPage(),results=[],errors=[];p.setDefaultTimeout(7000);p.setDefaultNavigationTimeout(30000);p.on('pageerror',e=>errors.push(e.message));
async function load(route='/assessment',s='PT05',width=1440,lang='zh'){await p.setViewportSize({width,height:width<700?844:1000});await p.goto('http://127.0.0.1:5184/plan');await p.evaluate(({s,k,lang})=>{localStorage.setItem(k,JSON.stringify(s));localStorage.setItem('career-prototype-language',lang);localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true}));},{s:typeof s==='string'?scenarioState(s):s,k:KEY,lang});await p.goto('http://127.0.0.1:5184'+route);await p.locator('.page-surface').waitFor();await p.addStyleTag({content:'*,*::before,*::after{animation:none!important;transition:none!important}'});}
const state=()=>p.evaluate(k=>JSON.parse(localStorage.getItem(k)),KEY);
async function shot(name,selector='.assessment-hub',top=false){const el=p.locator(selector);if(top)await p.evaluate(()=>scrollTo(0,0));else await el.evaluate(e=>e.scrollIntoView({block:'start'}));await p.screenshot({path:dir+'/实际截图/'+name+'-视口.png'});const v=p.viewportSize(),r=await el.boundingBox();await p.setViewportSize({width:v.width,height:Math.ceil(r.height+700)});const style=await p.addStyleTag({content:'.flow-progress{visibility:hidden!important}'});await el.screenshot({path:dir+'/实际截图/'+name+'-板块.png'});await style.evaluate(e=>e.remove());await p.setViewportSize(v);}
async function check(name,fn){if(process.argv[2]==='links'&&!name.startsWith('旧五类'))return;try{await fn();results.push({name,status:'pass'});console.log('PASS',name);}catch(e){results.push({name,status:'fail',error:e.message});console.log('FAIL',name,e.message.slice(0,800));await p.screenshot({path:dir+'/失败-'+results.length+'.png'});}}
try{
await check('默认总览合并四区，主模式仅两个，查看不改业务记录',async()=>{const s=scenarioState('PT05');await load('/assessment',s);assert.equal(await p.locator('.assessment-mode-tabs>a').count(),2);for(const id of ['assessment-review','assessment-profile','assessment-analysis','assessment-resumes'])assert.equal(await p.locator('#'+id).count(),1);const current=await state();for(const key of ['claims','goal','budget','analysis','resumes','tasks'])assert.deepEqual(current[key],s[key]);await shot('1440-总览-有材料','.assessment-hub',true);await shot('1440-画像同页','#assessment-profile');await shot('1440-差距同页','#assessment-analysis');await shot('1440-简历同页','#assessment-resumes');});
await check('总览直接核对候选，原确认回执与画像数据同步，拒绝记录不混入',async()=>{const s=scenarioState('PT05');s.claims.push({id:'pending',title:'待核对课程记录（合成）',text:'本人整理了资料并说明局限（合成）',contribution:'本人整理',type:'课程项目',skill:'SQL',aid:'无',status:'待确认',version:1});await load('/assessment',s);await shot('1440-待办同页','#assessment-review');await p.locator('.hub-review-list').getByRole('button',{name:'修正 / 确认此项',exact:true}).click();await p.getByRole('button',{name:'确认这一项并查看回执',exact:true}).click();assert.equal((await state()).claims.find(c=>c.id==='pending').status,'已确认');assert.equal((await state()).analysis,null);assert.equal(await p.locator('.assessment-hub').count(),1);assert.match(await p.locator('.assessment-hub-jumps').innerText(),/3 项已确认/);assert.equal(await p.locator('.hub-review-list').count(),0);assert.equal(await p.getByRole('button',{name:'查看全部材料与处置',exact:true}).count(),1);});
await check('方向切换与旧快照分开，只有明确操作才更新模拟分析',async()=>{const s=scenarioState('PT05');s.analysis=makeAnalysis(s);await load('/assessment',s);await p.getByLabel('对照职业范围',{exact:true}).selectOption('ops');assert.equal((await state()).goal,'data');assert.equal((await state()).analysis.occupation,'data');assert.match(await p.locator('.hub-snapshot-state').innerText(),/另一个职业方向/);await p.getByRole('button',{name:'展开模拟评估',exact:true}).click();await p.getByRole('button',{name:'显式更新模拟分析',exact:true}).click();assert.equal((await state()).analysis.occupation,'ops');assert.equal((await state()).analysisHistory.length,1);await shot('1440-展开评估','#assessment-analysis');});
await check('旧五类链接仍可用，定位、原文档案与地图返回参数保留',async()=>{for(const [tab,id,selector] of [['原文确认','assessment-review','.hub-expanded .record'],['成果档案','assessment-profile','#profile-evidence'],['四维与差距','assessment-analysis','.hub-expanded .panel'],['当前简历','assessment-resumes','.current-resumes']]){await load('/assessment?tab='+tab+'&mapReturn='+encodeURIComponent('/career-map?career=ops')+'#'+id);assert.equal(await p.locator(selector).count()>0,true);await p.waitForFunction(id=>document.activeElement?.id===id,id);assert.equal(await p.locator('#'+id).evaluate(e=>document.activeElement===e),true);assert.equal(new URL(p.url()).searchParams.get('mapReturn'),'/career-map?career=ops');}await load('/assessment?tab=我的画像#profile-evidence');await p.waitForFunction(()=>document.activeElement?.id==='profile-evidence');assert.equal(await p.locator('#profile-evidence').evaluate(e=>document.activeElement===e),true);await load('/assessment?resumeType=技能记录');assert.equal(await p.locator('#resume-material-form').count(),1);assert.equal(await p.locator('.assessment-hub').count(),0);});
await check('同页管理简历版本保持分目标选择，上传仍逐项核对',async()=>{const s=scenarioState('PT05');s.resumes=[{id:'target',title:'目标版（合成）',target:'job-a',version:1,date:'2026-10-22',claimIds:['claim-demo'],educationFacts:[]},{id:'general',title:'通用版（合成）',target:'',version:1,date:'2026-10-22',claimIds:['claim-sql'],educationFacts:[]}];s.currentResumeByTarget={'job-a':'saved:target'};await load('/assessment',s);assert.match(await p.locator('.hub-current-list').innerText(),/目标版/);await p.getByRole('button',{name:'管理全部简历版本',exact:true}).click();await p.locator('.resume-library-row').filter({hasText:'通用版（合成）'}).getByRole('button',{name:'设为此目标当前简历',exact:true}).click();assert.equal((await state()).currentResumeByTarget['job-a'],'saved:target');assert.equal((await state()).currentResumeByTarget[''],'saved:general');await p.getByRole('button',{name:'收起版本管理',exact:true}).click();assert.equal(await p.locator('.hub-current-list>li').count(),2);await shot('1440-当前版本','#assessment-resumes');await p.getByRole('button',{name:'上传 PDF / 粘贴简历',exact:true}).click();assert.equal(await p.locator('.resume-import-panel').count(),1);assert.equal((await state()).claims.length,2);});
await check('空态、手机、英文与长标题可读，无重复ID或横向溢出',async()=>{for(const [name,scene,width,lang] of [['1440-总览-空态','PT01',1440,'zh'],['390-总览-空态','PT01',390,'zh'],['390-总览-有材料','PT05',390,'zh'],['390-总览-English','PT01',390,'en']]){await load('/assessment',scene,width,lang);assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert.deepEqual(await p.locator('.assessment-hub [id]').evaluateAll(es=>es.map(e=>e.id).filter((id,i,a)=>a.indexOf(id)!==i)),[]);await shot(name,'.assessment-hub',true);if(lang==='en')assert.equal((await p.locator('.assessment-hub').innerText()).match(/[\u4e00-\u9fff]+/g),null);if(width===390){await shot(name+'-画像','#assessment-profile');await shot(name+'-底部','#assessment-resumes');}}const long=scenarioState('PT03');long.claims[2].title='很长的待确认经历记录'.repeat(50);await load('/assessment',long,390);assert.equal(await p.locator('.assessment-hub').evaluate(e=>e.scrollWidth>e.clientWidth),false);});
await check('资料录入在原工作区继续，保存后回同页确认而不自动确认',async()=>{await load('/assessment?tab=资料经历','PT01');await p.locator('.experience-story-nav button').nth(1).click();await p.locator('#experience-action').fill('本人整理课程资料（合成）');await p.locator('#experience-title').fill('新经历（合成）');await p.getByRole('button',{name:'保存，去核对经历',exact:true}).click();assert.equal(await p.locator('.assessment-hub').count(),1);assert.equal(await p.locator('#assessment-review .record').count(),1);assert.equal((await state()).claims[0].status,'待确认');assert.equal((await state()).analysis,null);});
assert.deepEqual(errors,[]);results.push({name:'浏览器运行时异常',status:'pass',count:0});
}finally{await fs.writeFile(dir+(process.argv[2]==='links'?'/旧链接定向复核.json':'/浏览器验收.json'),JSON.stringify({results,errors},null,2));await b.close();}if(results.some(r=>r.status==='fail'))process.exitCode=1;
